L1: // Proves the published file set without creating an archive: every required file
L2: // is present and no nested upstream clone leaks into the package.
L3: //
L4: // `npm pack` is the source of truth for what ships, so its JSON output is
L5: // external input and is parsed as `unknown`.
L6: import { execFileSync } from "node:child_process";
L7: import { errorMessage, isRecord, isString, parseJsonUnknown } from "../types/index.js";
L8: import { isUnknownArray, packageRoot } from "./support.js";
L9: const REQUIRED_FILES = [
L10:     "bin/junamis-skills.js",
L11:     "dist/index.js",
L12:     "dist/index.d.ts",
L13:     "dist/types/index.js",
L14:     "dist/types/index.d.ts",
L15:     "dist/cli.js",
L16:     "dist/guide.js",
L17:     "dist/orchestrator/cli.js",
L18:     "dist/design/cli.js",
L19:     "dist/reconcile/cli.js",
L20:     "scripts/orchestrator-state.mjs",
L21:     "scripts/design-registry.mjs",
L22:     "scripts/reconcile.mjs",
L23:     "docs/design/_schema.md",
L24:     "docs/RECONCILE.md",
L25:     "library/agents/orchestrator.md",
L26:     "library/skills/route/SKILL.md",
L27:     "library/RESUME.md",
L28:     "skills-lock.json",
L29:     "junamis-skills.yml",
L30:     "SECURITY.md",
L31: ];
L32: const EXCLUDED_PREFIXES = ["skills/", "nestjs-agent-skills/"];
L33: function packedFilesOf(manifest) {
L34:     const [pack] = isUnknownArray(manifest) ? manifest : [];
L35:     if (!isRecord(pack) || !isUnknownArray(pack["files"])) {
L36:         throw new Error("npm pack returned no file manifest");
L37:     }
L38:     const files = new Set();
L39:     for (const file of pack["files"]) {
L40:         if (!isRecord(file) || !isString(file["path"])) {
L41:             throw new Error("npm pack returned an invalid file entry");
L42:         }
L43:         files.add(file["path"]);
L44:     }
L45:     return { files, unpackedSize: pack["unpackedSize"] };
L46: }
L47: function main() {
L48:     const output = execFileSync("npm", ["pack", "--dry-run", "--json"], {
L49:         cwd: packageRoot,
L50:         encoding: "utf8",
L51:     });
L52:     const parsed = parseJsonUnknown(output);
L53:     if (!parsed.ok)
L54:         throw new Error(`npm pack returned invalid JSON: ${parsed.error.message}`);
L55:     const { files, unpackedSize } = packedFilesOf(parsed.value);
L56:     const missing = REQUIRED_FILES.filter((file) => !files.has(file));
L57:     if (missing.length > 0)
L58:         throw new Error(`package is missing required files: ${missing.join(", ")}`);
L59:     const leaked = [...files].filter((file) => EXCLUDED_PREFIXES.some((prefix) => file.startsWith(prefix)));
L60:     if (leaked.length > 0)
L61:         throw new Error(`package includes nested upstream clones: ${leaked.join(", ")}`);
L62:     console.log(`package contents valid: ${files.size} files, ${String(unpackedSize)} unpacked bytes`);
L63: }
L64: /** CLI entry. The launcher in `scripts/` calls this. */
L65: export function run() {
L66:     try {
L67:         main();
L68:     }
L69:     catch (error) {
L70:         console.error(`package contents invalid: ${errorMessage(error)}`);
L71:         process.exitCode = 1;
L72:     }
L73: }

