        command: argv[0] ?? "help",
        force: false,
        dryRun: false,
        dir: process.cwd(),
        agent: "opencode",
        scope: null,
    };
    for (let i = 1; i < argv.length; i++) {
        const a = argv[i];
        if (a === "--force")
            args.force = true;
        else if (a === "--dry-run")
            args.dryRun = true;
        else if (a === "--dir")
            args.dir = resolve(requireValue(argv, ++i, a));
        else if (a === "--agent")
            args.agent = requireValue(argv, ++i, a);
        else if (a === "--scope")
