        content = content
            .replace(/"\{env:HOME\}\/\.config\/junamis\/skills\/skills"/g, '"./.config/junamis/skills/skills"')
            .replace(/"\{env:HOME\}\/\.config\/junamis\/skills\/\*\.md"/g, '"./.config/junamis/skills/*.md"')
            .replace(/"\{env:HOME\}\/\.agents\/skills"/g, '"./.agents/skills"');
