        counts[a.action] = (counts[a.action] ?? 0) + 1;
    }
    const summary = Object.entries(counts).map(([k, v]) => `${v} ${k}`).join(", ") || "nothing";
    console.log(`${c.cyan("library")} for ${args.agent} (junamis-skills ${version}, ${scope}): ${c.gray(summary)}`);
    if (args.dryRun) {
        for (const a of result.actions)
            console.log(`  ${a.action.padEnd(24)} ${c.gray(a.path)}`);
        for (const a of result.linkActions ?? [])
            console.log(`  ${a.action.padEnd(24)} ${c.gray(a.path)} -> ${c.gray(String(a.target))}`);
    }
    for (const p of result.stale)
        console.log(`  ${args.dryRun ? "would remove" : "removed"} stale ${c.gray(p)}`);
    for (const warning of result.warnings ?? [])
        console.warn(c.yellow(`  warning: ${warning}`));
